import urllib.request, urllib.parse, json
def get(url):
 req=urllib.request.Request(url,headers={'User-Agent':'Mozilla/5.0'});
 with urllib.request.urlopen(req,timeout=30) as r:return json.load(r)
item_id='306c580063184ab99bfa2c9e348be039'
info=get('https://www.arcgis.com/sharing/rest/content/items/'+item_id+'?f=json')
print('KNOWN_ITEM_OWNER',info.get('owner'),'ORG',info.get('orgId'),'TITLE',info.get('title'),'TYPE',info.get('type'))
owners=[info.get('owner')]
terms=['MDT','MDS','LIDAR','elevacao','altimetria','curva nivel','cartografia','terreno','modelo digital']
for owner in owners:
 for term in terms:
  q=f'owner:{owner} {term}'
  data=get('https://www.arcgis.com/sharing/rest/search?'+urllib.parse.urlencode({'q':q,'f':'json','num':100}))
  if data.get('total'):
   print('QUERY',q,'TOTAL',data.get('total'))
   for it in data.get('results',[]):
    print('ITEM',it.get('id'),it.get('type'),repr(it.get('title')), 'URL',it.get('url'))
# org-wide search if orgId available
org=info.get('orgId')
if org:
 for term in terms:
  q=f'orgid:{org} {term}'
  data=get('https://www.arcgis.com/sharing/rest/search?'+urllib.parse.urlencode({'q':q,'f':'json','num':100}))
  if data.get('total'):
   print('ORGQUERY',q,'TOTAL',data.get('total'))
   for it in data.get('results',[]): print('ORGITEM',it.get('id'),it.get('type'),it.get('owner'),repr(it.get('title')),'URL',it.get('url'))
